const results = [];
for (const item of $input.all()) {
  const b = item.json.body || item.json;
  const repo = (b.repository && (b.repository.full_name || b.repository.name)) || '';
  const commits = b.commits || [];
  for (const c of commits) {
    const files = [...(c.added || []), ...(c.modified || []), ...(c.removed || [])];
    results.push({
      json: {
        source: 'push',
        repo,
        component: files[0] || 'unknown',
        filesChanged: files,
        contributor: (c.author && (c.author.username || c.author.email || c.author.name)) || 'unknown',
        commitId: c.id || '',
        message: c.message || '',
        timestamp: c.timestamp || new Date().toISOString()
      }
    });
  }
}
return results;

const b = $input.item.json.body || $input.item.json;
const pr = b.pull_request || {};

return {
  json: {
    source: 'review',
    repo: (b.repository && (b.repository.full_name || b.repository.name)) || '',
    component: (pr.changed_files_sample && pr.changed_files_sample[0]) || pr.title || 'unknown',
    contributor: (pr.user && pr.user.login) || 'unknown',
    reviewers: (pr.requested_reviewers || []).map(r => r.login),
    mergedBy: (pr.merged_by && pr.merged_by.login) || '',
    prNumber: pr.number || '',
    timestamp: pr.merged_at || new Date().toISOString()
  }
};

const results = [];
for (const item of $input.all()) {
  const repoFullName = item.json.full_name || item.json.repo || '';
  const stats = item.json.body || item.json || [];
  const list = Array.isArray(stats) ? stats : (stats.contributors || []);
  for (const c of list) {
    results.push({
      json: {
        source: 'baseline',
        repo: repoFullName,
        component: repoFullName,
        contributor: (c.author && c.author.login) || 'unknown',
        totalCommits: c.total || 0,
        lastCommitWeek: (c.weeks && c.weeks.length) ? c.weeks[c.weeks.length - 1].w : null,
        timestamp: new Date().toISOString()
      }
    });
  }
}
return results;

// Pull the signal list out of whatever the buffer API returned
const signals = ($input.first().json.signals || $input.first().json || []);
const list = Array.isArray(signals) ? signals : [];

function clusterKey(s) {
  return [(s.repo || '').toLowerCase(), (s.component || '').toLowerCase()].join('|');
}

const groups = {};
for (const s of list) {
  const key = clusterKey(s);
  if (!groups[key]) groups[key] = [];
  groups[key].push(s);
}

const clearClusters = [];
const ambiguousClusters = [];

for (const key of Object.keys(groups)) {
  const members = groups[key];
  const contributorCommits = {};
  for (const m of members) {
    const c = m.contributor || 'unknown';
    contributorCommits[c] = (contributorCommits[c] || 0) + (m.totalCommits || 1);
  }
  const contributors = Object.keys(contributorCommits);
  const totalCommits = Object.values(contributorCommits).reduce((a, b) => a + b, 0);
  const topContributor = contributors.reduce((top, c) => contributorCommits[c] > (contributorCommits[top] || 0) ? c : top, contributors[0]);
  const topShare = totalCommits > 0 ? contributorCommits[topContributor] / totalCommits : 0;

  const cluster = {
    clusterKey: key,
    repo: members[0].repo,
    component: members[0].component,
    contributors,
    contributorCommits,
    topContributor,
    topShare,
    members
  };

  // Clearly healthy: 3+ active contributors, no single owner above 60% of commits
  if (contributors.length >= 3 && topShare < 0.6) {
    clearClusters.push({ ...cluster, resolution: 'healthy' });
    continue;
  }
  // Clearly critical: single contributor, or one owner has 90%+ of commits
  if (contributors.length === 1 || topShare >= 0.9) {
    clearClusters.push({ ...cluster, resolution: 'critical-risk' });
    continue;
  }
  // Otherwise ambiguous - e.g. 2 contributors with 60-90% concentration - let Claude judge context
  ambiguousClusters.push(cluster);
}

return [{
  json: {
    windowTimestamp: new Date().toISOString(),
    clearClusters,
    ambiguousClusters,
    hasAmbiguous: ambiguousClusters.length > 0
  }
}];

