=You are a staff engineer assessing code ownership and bus-factor risk.

Below are components where ownership is concentrated among only one or two active contributors, but the concentration level alone isn't enough to classify them automatically:

{{ JSON.stringify($json.ambiguousClusters, null, 2) }}

For each cluster, decide whether this represents a genuine bus-factor risk that warrants a knowledge-transfer or documentation task, or whether it's acceptable as-is (for example, a stable, low-churn component, or one where the secondary contributors are simply less active but still present and capable). Base this on contributor count, commit concentration, and the component's apparent criticality from its repo/path/name.

Return a JSON object with EXACTLY this shape:
{
  "resolvedClusters": [
    {
      "clusterKey": "string, matching input exactly",
      "resolution": "critical-risk" or "acceptable",
      "recommendedAction": "one short phrase, e.g. 'pair programming session' or 'no action needed'",
      "reasoning": "one short sentence"
    }
  ]
}

Return ONLY the JSON. No markdown, no explanation.

parameters.jsCode:
const item = $input.item.json;
const upstream = $('Check for Ambiguous Clusters').first().json;

let resolved = [];
try {
  const rawText = item.output || item.text || item.response || '{}';
  const clean = rawText.replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(clean);
  resolved = parsed.resolvedClusters || [];
} catch (e) {
  // Fallback: if parsing fails, flag every ambiguous cluster as critical-risk (safer than silently dismissing a real bus-factor risk)
  resolved = (upstream.ambiguousClusters || []).map(c => ({
    clusterKey: c.clusterKey,
    resolution: 'critical-risk',
    recommendedAction: 'manual review',
    reasoning: 'AI risk assessment unavailable this cycle; flagged as risk as a safety default.'
  }));
}

const resolutionByKey = {};
for (const r of resolved) resolutionByKey[r.clusterKey] = r;

const finalizedAmbiguous = (upstream.ambiguousClusters || []).map(c => {
  const r = resolutionByKey[c.clusterKey];
  return {
    ...c,
    resolution: r ? r.resolution : 'critical-risk',
    recommendedAction: r ? r.recommendedAction : 'manual review',
    aiReasoning: r ? r.reasoning : ''
  };
});

return { json: { windowTimestamp: upstream.windowTimestamp, clusters: [...upstream.clearClusters, ...finalizedAmbiguous] } };

const allClusters = [];
for (const item of $input.all()) {
  for (const c of (item.json.clusters || [])) allClusters.push(c);
}

const tasks = allClusters
  .filter(c => c.resolution === 'critical-risk')
  .map((c, idx) => ({
    taskId: `${(c.repo || 'unknown').replace(/\//g, '-')}-${(c.component || 'component').replace(/[\\/]/g, '-')}-${idx}`,
    title: `Bus-factor risk: ${c.component || 'component'} in ${c.repo || 'unknown repo'}`,
    repo: c.repo || '',
    component: c.component || '',
    topContributor: c.topContributor || '',
    topShare: c.topShare || null,
    contributorCount: (c.contributors || []).length,
    recommendedAction: c.recommendedAction || 'knowledge transfer / documentation',
    aiReasoning: c.aiReasoning || '',
    priority: ((c.topShare || 0) >= 0.9 || (c.contributors || []).length === 1) ? 'high' : 'medium'
  }));

return [{ json: { windowTimestamp: new Date().toISOString(), tasks } }];
